-- ════════════════════════════════════════════════════════════════════════════
-- Orders to restaurants, owners who run them, and Safal's full two-week menu
--
-- 1. messes.owner_emails: who runs a restaurant. They may sign in with that address (any domain,
--    like admins) and see its orders at /orders. Set in Admin › Campus, never in this file.
--    messes.orders_open: the owner is taking orders on the site right now (their switch).
-- 2. mess_orders: one row per order a signed-in student placed. Prices are copied from the
--    restaurant's list when the order is placed (the browser's prices are never trusted). Only a
--    hash of the student's network is kept, for the daily limits. Server only, like the rest.
-- 3. Safal hostel mess gets week 2 (from 19 Oct) and the real meal times from the notice, but only
--    while it still has the single week first seeded (an admin's edits are never overwritten).
--
-- Safe to run more than once. Rollback:
--   drop table if exists public.mess_orders;
--   alter table public.messes drop column if exists owner_emails, drop column if exists orders_open;
-- ════════════════════════════════════════════════════════════════════════════

alter table public.messes add column if not exists owner_emails text[]  not null default '{}';
alter table public.messes add column if not exists orders_open  boolean not null default false;

create table if not exists public.mess_orders (
  id          uuid primary key default gen_random_uuid(),
  code        text not null,
  mess_slug   text not null references public.messes(slug) on delete cascade,
  user_id     uuid not null,
  email       text not null default '',
  lines       jsonb not null,
  total       int not null,
  mode        text not null,
  address     text not null default '',
  name        text not null default '',
  phone       text not null,
  note        text not null default '',
  status      text not null default 'placed',
  owner_note  text not null default '',
  ip_hash     text not null default '',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint mess_orders_mode check (mode in ('delivery', 'pickup')),
  constraint mess_orders_status check (status in ('placed', 'accepted', 'ready', 'done', 'rejected', 'cancelled')),
  constraint mess_orders_phone check (phone ~ '^[6-9][0-9]{9}$'),
  constraint mess_orders_lines check (jsonb_typeof(lines) = 'array' and pg_column_size(lines) < 20000),
  constraint mess_orders_total check (total between 0 and 1000000)
);
create index if not exists mess_orders_mess on public.mess_orders (mess_slug, created_at desc);
create index if not exists mess_orders_user on public.mess_orders (user_id, created_at desc);
create index if not exists mess_orders_ip on public.mess_orders (ip_hash, created_at desc);
alter table public.mess_orders enable row level security; -- server only
revoke all on public.mess_orders from anon, authenticated;
comment on table public.mess_orders is 'Orders students placed with restaurants for day scholars (owners see them at /orders).';

